@Slf4j
@Component
@RequiredArgsConstructor
public class AllJobExecutionProvider implements JobExecutionProvider {

    private final JobExplorer jobExplorer;

    public Collection<JobExecution> getJobExecutions(Optional<String> jobNameRegexp,
                                                     Optional<String> exitCode,
                                                     int limitPerJob) {
        log.debug("Getting job executions from JobExplorer for jobNameRegexp={}, exitCode={}, limitPerJob={}", jobNameRegexp, exitCode, limitPerJob);
        Optional<Pattern> maybeJobNamePattern = jobNameRegexp.map(Pattern::compile);
        List<String> jobNames = jobExplorer.getJobNames().stream()
                .filter(n -> maybeJobNamePattern.map(p -> p.matcher(n).matches()).orElse(true)).collect(toList());
        TreeSet<JobExecution> result = new TreeSet<>(byDescendingTime());
        for (String jobName : jobNames)
            jobExplorer.getJobInstances(jobName, 0, limitPerJob).stream()
                    .flatMap(ji ->jobExplorer.getJobExecutions(ji).stream())
                    .filter(e -> exitCode.map(c -> e.getExitStatus().getExitCode().equals(c)).orElse(true))
                    .sorted(byDescendingTime())
                    .limit(limitPerJob).forEach(result::add);
        log.debug("Found {} job execution(s) for jobNameRegexp={}, exitCode={}, limitPerJob={}",
                jobNameRegexp, exitCode, limitPerJob, result.size());
        return result;
    }
}

public interface JobExecutionProvider {

    Collection<JobExecution> getJobExecutions(Optional<String> jobNameRegexp,
                                        Optional<String> exitCode,
                                        int limitPerJob);

    default Comparator<JobExecution> byDescendingTime() {
        return (j1, j2) -> {
            int result;
            if (j1.getEndTime() != null && j2.getEndTime() != null)
                result = j1.getEndTime().compareTo(j2.getEndTime());
            else
                result = j1.getStartTime().compareTo(j2.getStartTime());
            return result * -1;
        };
    }
}

@Slf4j
@Aspect
@Component
public class JobExecutionAspect {

    private Set<Consumer<JobExecution>> consumers = new LinkedHashSet<>();

    public void register(Consumer<JobExecution> consumer) {
        consumers.add(consumer);
    }

    @Before("within(org.springframework.batch.core.repository.JobRepository+) && execution(* update(..)) && args(jobExecution)")
    public void jobExecutionUpdated(JobExecution jobExecution) {
        if (jobExecution.getStatus().isUnsuccessful())
            log.error("{} {}: {}", jobExecution.getStatus().name(), jobExecution.getJobInstance().getJobName(), jobExecution);
        else
            log.info("{} {}: {}", jobExecution.getStatus().name(), jobExecution.getJobInstance().getJobName(), jobExecution);
        consumers.forEach(l -> l.accept(jobExecution));
    }
}

@Component @RequiredArgsConstructor
public class JobBuilder {
    private final JobRegistry jobRegistry;
    private final JobBuilderFactory jobs;
    private final StepBuilderFactory steps;
    private final Environment environment;

    public static Job registerJob(JobRegistry jobRegistry, Job job) {
        jobRegistry.unregister(job.getName());
        try {
            jobRegistry.register(new JobFactory() {
                @Override
                public Job createJob() {
                    return job;
                }

                @Override
                public String getJobName() {
                    return job.getName();
                }
            });
        } catch (Exception e) {
            throw new RuntimeException("Could not create " + job.getName(), e);
        }
        return job;
    }

    public Job registerJob(Job job) {
        return registerJob(jobRegistry, job);
    }

    public Job createJob(String name, Runnable runnable) {
        return createJob(name, new RunnableTasklet(runnable));
    }

    private Job createJob(String name, Tasklet tasklet) {
        return registerJob(jobs.get(name).incrementer(new RunIdIncrementer())
                .start(steps.get("step").allowStartIfComplete(true).tasklet(tasklet).build()).build());
    }

    public Job createJob(String name, Consumer<PropertyResolver> propertyResolverConsumer) {
        return createJob(name, new PropertyResolverConsumerTasklet(environment, propertyResolverConsumer));
    }

    public Job createJobFromStepExecutionConsumer(String name, Consumer<StepExecution> stepExecutionConsumer) {
        return createJob(name, new StepExecutionListenerTasklet(stepExecutionConsumer));
    }
}

public class JobParamUtil {

	public static JobParameters convertRawToJobParams(Map<String, Object> properties) {
		return new JobParameters(convertRawToParamMap(properties));
	}

	public static Map<String, JobParameter> convertRawToParamMap(Map<String, Object> properties) {
		return Optional.ofNullable(properties).orElse(emptyMap()).entrySet().stream()
				.collect(toMap(Map.Entry::getKey, e -> createJobParameter(e.getValue())));
	}

	public static JobParameter createJobParameter(Object value) {
		if (value instanceof Date)
			return new JobParameter((Date) value);
		else if (value instanceof Long)
			return new JobParameter((Long) value);
		else if (value instanceof Double)
			return new JobParameter((Double) value);
		else
			return new JobParameter("" + value);
	}
}

